    /**
     * Method to retrieve the Person via PersonFetchOneSummary
     * @param 	summary PersonFetchOneSummary 
     * @return 	PersonFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Person getPerson( PersonFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PersonFetchOneSummary arg cannot be null" );
    	
    	Person entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Person
        	// --------------------------------------
        	CompletableFuture<Person> futureEntity = queryGateway.query(new FindPersonQuery( new LoadPersonFilter( summary.getPersonId() ) ), ResponseTypes.instanceOf(Person.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Person with id " + summary.getPersonId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


